DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.plm_validate_payload(text,jsonb,uuid,uuid,uuid,boolean)'::regprocedure) INTO definition; definition:=replace(definition,'IF ent.id=ref.entity_id THEN','IF ent.id=(SELECT entity_id FROM public.plm_revisions WHERE id=_item) THEN'); definition:=replace(definition,'RETURN findings;', $replacement$IF _strict AND _kind='ITEM' AND _payload->>'makeBuy'='MAKE' THEN IF NOT EXISTS(SELECT 1 FROM public.plm_revisions r JOIN public.plm_entities e ON e.id=r.entity_id WHERE r.organization_id=_org AND r.item_revision_id IN (SELECT id FROM public.plm_revisions WHERE payload=_payload AND organization_id=_org) AND e.kind='ROUTING' AND r.state='RELEASED') THEN findings:=findings||jsonb_build_array('Manufactured item lacks a compatible released route'); END IF; IF NOT EXISTS(SELECT 1 FROM public.plm_revisions r JOIN public.plm_entities e ON e.id=r.entity_id WHERE r.organization_id=_org AND r.item_revision_id IN (SELECT id FROM public.plm_revisions WHERE payload=_payload AND organization_id=_org) AND e.kind='BOM' AND r.state='RELEASED') THEN findings:=findings||jsonb_build_array('Manufactured item lacks a compatible released material definition'); END IF; END IF; IF _strict AND _kind='DOCUMENT' AND NOT EXISTS(SELECT 1 FROM public.plm_document_files f WHERE f.organization_id=_org AND f.sha256=_payload->>'fileSha256') THEN findings:=findings||jsonb_build_array('Verified immutable file required'); END IF; RETURN findings;$replacement$); EXECUTE definition; END $$;